    }

    @Test
    void sameKeySameParamsReturnsFirstResultAndSameKeyDifferentParamsConflicts() {
        var first = service.startOnWarning(warning("WARN-IDEMP", new BigDecimal("3.00"),
                new BigDecimal("60.00")));
        assertThat(first.replay()).isFalse();
