                        VALUES (?, ?, ?, ?, ?, ?)
                        """,
                requestId, requestType, fingerprint, responseStatus, responseBody,
                Timestamp.valueOf(LocalDateTime.now()));
        return true;
    } catch (DuplicateKeyException e) {
        return false;
    }
